window.EXAM={"sections":{"listening":[{"title":"University Clubs","html":"<h3>Questions 1–4</h3><p class=\"direction\">Complete the table below. Write NO MORE THAN THREE WORDS AND/OR A NUMBER for each answer.</p><h3>University Clubs</h3><div class=\"table-scroll\"><table class=\"exam-table\"><thead><tr><th></th><th>Monday</th><th>Tuesday</th><th>Wednesday</th></tr></thead><tbody><tr><th>Name of club</th><td>film</td><td>climbing</td><td>chess</td></tr><tr><th>Extra activities</th><td>discussions</td><td id=\"question-1\">{{1}}</td><td id=\"question-2\">{{2}}</td></tr><tr><th>Current number of members</th><td id=\"question-3\">{{3}}</td><td>40</td><td>55</td></tr><tr><th>Contact</th><td>Events organiser</td><td id=\"question-4\">{{4}}</td><td>Maths tutor</td></tr></tbody></table></div><h3>Questions 5–10</h3><p class=\"direction\">Complete the notes below. Write NO MORE THAN THREE WORDS for each answer.</p><h3>Details of climbing club</h3><div class=\"text-question\" id=\"question-5\"><span class=\"qn\">5.</span> meets <span class=\"live-input\">{{5}}</span>  <button class=\"flag-btn\" data-flag=\"5\" title=\"Flag question 5\">⚐</button></div><div class=\"text-question\" id=\"question-6\"><span class=\"qn\">6.</span> excursion to France in the <span class=\"live-input\">{{6}}</span>  <button class=\"flag-btn\" data-flag=\"6\" title=\"Flag question 6\">⚐</button></div><div class=\"text-question\" id=\"question-7\"><span class=\"qn\">7.</span> subscriptions paid <span class=\"live-input\">{{7}}</span>  <button class=\"flag-btn\" data-flag=\"7\" title=\"Flag question 7\">⚐</button></div><h3>Benefits</h3><div class=\"text-question\" id=\"question-8\"><span class=\"qn\">8.</span> discounts on <span class=\"live-input\">{{8}}</span>  <button class=\"flag-btn\" data-flag=\"8\" title=\"Flag question 8\">⚐</button></div><div class=\"text-question\" id=\"question-9\"><span class=\"qn\">9.</span> annual <span class=\"live-input\">{{9}}</span>  <button class=\"flag-btn\" data-flag=\"9\" title=\"Flag question 9\">⚐</button></div><div class=\"text-question\" id=\"question-10\"><span class=\"qn\">10.</span> free entrance to climbing <span class=\"live-input\">{{10}}</span> in Cardiff <button class=\"flag-btn\" data-flag=\"10\" title=\"Flag question 10\">⚐</button></div>"},{"title":"Library System","html":"<h3>Questions 11–15</h3><p class=\"direction\">Label the plan. Choose FIVE answers from A–G and write the correct letter for questions 11–15.</p><div class=\"option-box\"><strong>Library sections</strong><div><b>A</b> Arts section</div><div><b>B</b> Computers</div><div><b>C</b> Languages section</div><div><b>D</b> Law</div><div><b>E</b> Magazines</div><div><b>F</b> Science</div><div><b>G</b> study desks</div></div><img src=\"listening-library-plan.svg\" class=\"question-diagram library-diagram\" alt=\"Library plan with numbered locations 11 to 15\"><div class=\"inline-answer-grid\"><div class=\"question-group\"><div class=\"question-line\" id=\"question-11\"><span class=\"qn\">11.</span> Library location 11 <span class=\"live-input\">{{11}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"11\" title=\"Flag question 11\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-12\"><span class=\"qn\">12.</span> Library location 12 <span class=\"live-input\">{{12}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"12\" title=\"Flag question 12\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-13\"><span class=\"qn\">13.</span> Library location 13 <span class=\"live-input\">{{13}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"13\" title=\"Flag question 13\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-14\"><span class=\"qn\">14.</span> Library location 14 <span class=\"live-input\">{{14}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"14\" title=\"Flag question 14\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-15\"><span class=\"qn\">15.</span> Library location 15 <span class=\"live-input\">{{15}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"15\" title=\"Flag question 15\">⚐</button></div></div></div><h3>Questions 16–20</h3><p class=\"direction\">Complete the notes below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer.</p><h3>Library system</h3><div class=\"text-question\" id=\"question-16\"><span class=\"qn\">16.</span> Maximum borrowing period: <span class=\"live-input\">{{16}}</span>  <button class=\"flag-btn\" data-flag=\"16\" title=\"Flag question 16\">⚐</button></div><div class=\"text-question\" id=\"question-17\"><span class=\"qn\">17.</span> Renew books in person or by: <span class=\"live-input\">{{17}}</span>  <button class=\"flag-btn\" data-flag=\"17\" title=\"Flag question 17\">⚐</button></div><div class=\"text-question\" id=\"question-18\"><span class=\"qn\">18.</span> Overdue charge: <span class=\"live-input\">{{18}}</span>  <button class=\"flag-btn\" data-flag=\"18\" title=\"Flag question 18\">⚐</button></div><div class=\"text-question\" id=\"question-19\"><span class=\"qn\">19.</span> Unavailable books: complete <span class=\"live-input\">{{19}}</span>  <button class=\"flag-btn\" data-flag=\"19\" title=\"Flag question 19\">⚐</button></div><div class=\"text-question\" id=\"question-20\"><span class=\"qn\">20.</span> Extra services: <span class=\"live-input\">{{20}}</span>  <button class=\"flag-btn\" data-flag=\"20\" title=\"Flag question 20\">⚐</button></div>"},{"title":"University Courses","html":"<h3>Questions 21–23</h3><p class=\"direction\">What is the advantage of each course? Choose THREE answers from A–E.</p><div class=\"option-box\"><strong>Advantages of the Course</strong><div><b>A</b> will be tested in the final exams</div><div><b>B</b> will be useful for a future job</div><div><b>C</b> will help with research skills</div><div><b>D</b> will improve writing skills</div><div><b>E</b> will support material already covered</div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-21\"><span class=\"qn\">21.</span> Science and Ethics <span class=\"live-input\">{{21}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"21\" title=\"Flag question 21\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-22\"><span class=\"qn\">22.</span> Pharmacology Prelim <span class=\"live-input\">{{22}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"22\" title=\"Flag question 22\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-23\"><span class=\"qn\">23.</span> Reporting Test Results <span class=\"live-input\">{{23}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"23\" title=\"Flag question 23\">⚐</button></div></div><h3>Questions 24–30</h3><p class=\"direction\">Complete the sentences below. Write NO MORE THAN TWO WORDS for each answer.</p><div class=\"question-group\"><div class=\"question-line\" id=\"question-24\"><span class=\"qn\">24.</span> The Maths course will run in the ________. <span class=\"live-input\">{{24}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"24\" title=\"Flag question 24\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-25\"><span class=\"qn\">25.</span> The tutor for Pharmacology is visiting from ________. <span class=\"live-input\">{{25}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"25\" title=\"Flag question 25\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-26\"><span class=\"qn\">26.</span> ________ for the project must be submitted by the end of January. <span class=\"live-input\">{{26}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"26\" title=\"Flag question 26\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-27\"><span class=\"qn\">27.</span> Resources for experiments are available in the ________. <span class=\"live-input\">{{27}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"27\" title=\"Flag question 27\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-28\"><span class=\"qn\">28.</span> Extra ________ will be held in December. <span class=\"live-input\">{{28}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"28\" title=\"Flag question 28\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-29\"><span class=\"qn\">29.</span> Students are allowed to do presentations in ________. <span class=\"live-input\">{{29}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"29\" title=\"Flag question 29\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-30\"><span class=\"qn\">30.</span> Course assessment will be based on ________. <span class=\"live-input\">{{30}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"30\" title=\"Flag question 30\">⚐</button></div></div>"},{"title":"Exchange Rate Project","html":"<h3>Questions 31–36</h3><p class=\"direction\">Complete the flow chart below. Write ONE WORD ONLY for each answer.</p><img src=\"listening-exchange-rate-flow.svg\" class=\"question-diagram exchange-diagram\" alt=\"Exchange Rate Project flow chart, questions 31 to 36\"><div class=\"inline-answer-grid\"><div class=\"question-group\"><div class=\"question-line\" id=\"question-31\"><span class=\"qn\">31.</span> Exchange Rate Project <span class=\"live-input\">{{31}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"31\" title=\"Flag question 31\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-32\"><span class=\"qn\">32.</span> Exchange Rate Project <span class=\"live-input\">{{32}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"32\" title=\"Flag question 32\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-33\"><span class=\"qn\">33.</span> Exchange Rate Project <span class=\"live-input\">{{33}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"33\" title=\"Flag question 33\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-34\"><span class=\"qn\">34.</span> Exchange Rate Project <span class=\"live-input\">{{34}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"34\" title=\"Flag question 34\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-35\"><span class=\"qn\">35.</span> Exchange Rate Project <span class=\"live-input\">{{35}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"35\" title=\"Flag question 35\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-36\"><span class=\"qn\">36.</span> Exchange Rate Project <span class=\"live-input\">{{36}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"36\" title=\"Flag question 36\">⚐</button></div></div></div><h3>Questions 37–40</h3><p class=\"direction\">Answer the questions below. Write NO MORE THAN THREE WORDS AND/OR A NUMBER for each answer.</p><div class=\"question-group\"><div class=\"question-line\" id=\"question-37\"><span class=\"qn\">37.</span> How many main trading partners does the UK have? <span class=\"live-input\">{{37}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"37\" title=\"Flag question 37\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-38\"><span class=\"qn\">38.</span> Which sector does the tutor want students to study? <span class=\"live-input\">{{38}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"38\" title=\"Flag question 38\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-39\"><span class=\"qn\">39.</span> What does the tutor want students to look at changes in? <span class=\"live-input\">{{39}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"39\" title=\"Flag question 39\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-40\"><span class=\"qn\">40.</span> When does the tutor want the project completed by? <span class=\"live-input\">{{40}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"40\" title=\"Flag question 40\">⚐</button></div></div>"}],"reading":[{"title":"Trans Fatty Acids","passage":"<p class=\"passage-par\">A recent editorial in the British Medical Journal (BMJ), written by researchers from the University of Oxford, has called for food labels to list trans fats as well as cholesterol and saturated fat.</p>\n<p class=\"passage-par\">Trans fats (or trans fatty acids) are a type of unsaturated fatty acid. They occur naturally in small amounts in foods produced from ruminant animals* e.g. milk, beef and lamb. However, most of the trans fatty acids in the diet are produced during the process of partial hydrogenation (hardening) of vegetable oils into semi-solid fats. They are therefore found in hard margarines, partially hydrogenated cooking oils, and in some bakery products, fried foods, and other processed foods that are made using these.</p>\n<p class=\"passage-par\">Trans fatty acids have an adverse effect on certain chemicals, known as lipids, which are found in the blood and have been shown to increase the risk of heart disease. They also increase LDL-cholesterol (the &#x27;bad cholesterol&#x27;) and decrease HDL-cholesterol (the &#x27;good cholesterol&#x27;). They may also have adverse effects on cardiovascular disease risk that are independent of an effect on blood lipids (Mozaffarian et al. 2006).</p>\n<p class=\"passage-par\">In a recent review of prospective studies investigating the effects of trans fatty acids, a 2% increase in energy intake from trans fatty acids was associated with a 23% increase in the incidence of heart disease. The authors also reported that the adverse effects of trans fatty acids were observed even at very low intakes (3% of total daily energy intake, or about 2-7g per day) (Mozaffarian et al. 2006).</p>\n<p class=\"passage-par\">However, in this recent review it is only trans fatty acids produced during the hardening of vegetable oils that are found to be harmful to health. The public health implications of consuming trans fatty acids from ruminant products are considered to be relatively limited.</p>\n<p class=\"passage-par\">Over the last decade, population intakes of trans fatty acids in the UK fell and are now on average, well below the recommended 2% of total energy set by the Department of Health in 1991, at 1.2% of energy (Henderson et al. 2003). This is not to say that intakes of trans fatty acids are not still a problem, and dietary advice states that those individuals who are in the top end of the distribution of intake should still make efforts to reduce their intakes.</p>\n<p class=\"passage-par\">Currently, trans fatty acids in foods are labelled in the USA, but not in the UK and Europe. The UK Food Standards Agency (FSA) is in favour of the revision of the European directive that governs the content and format of food labels so that trans fatty acids are labelled. This should enable consumers to make better food choices with regard to heart health (Clarke &amp; Levington 2006).</p>\n<p class=\"passage-par\">Recognising the adverse health effects of trans fatty acids, many food manufacturers and retailers have been systematically removing them from their products in recent years. For example, they have been absent for some time from major brands of margarine and other fat spreads, which are now manufactured using a different technique. Also, many companies now have guidelines in place that are resulting in reformulation and reduction or elimination of trans fatty acids in products where they have in the past been found, such as snack products, fried products and baked goods. Consequently, the vast majority of savoury biscuits and crisps produced in the UK do not contain partially hydrogenated oils. Similarly, changes are being made to the way bakery products are manufactured. For example, a leading European manufacturer of major brands of biscuits, cakes and snacks has recently announced that these are now made without partially hydrogenated vegetable oils, a transition that began in 2004. Alongside these changes, the manufacturer has also reported a cut in the amount of saturates. It is clear that a major technical challenge in achieving such changes is to avoid simply exchanging trans fatty acids for saturated fatty acids, which also have damaging health effects.</p>\n<p class=\"passage-par\">Foods that are labelled as containing partially-hydrogenated oils or fats are a source of trans fatty acids (sometimes &#x27;partially-hydrogenated&#x27; fats are just labelled as &#x27;hydrogenated&#x27; fats). These foods include hard margarines, some fried products and some manufactured bakery products e.g. biscuits, pastries and cakes.</p>\n<p class=\"passage-par\">It is important to note that intake may have changed in the light of reformulation of foods that has taken place over the past six years in the UK, as referred to earlier. Furthermore, the average intake of trans fatty acids is lower in the UK than in the USA (where legislation has now been introduced). However, this does not mean there is room for complacency, as the intake in some sectors of the population is known to be higher than recommended.</p>\n<p class=\"passage-par\">*animals that mainly eat grass</p>\n<p class=\"source-note\">Source note: &#x27;Trans Fatty Acids&#x27; taken from British Medical Journal, 2006, Volume 333, p214, amended with permission from the BMJ Publishing Group.</p>","questions":"<h3>Questions 1–7</h3><p class=\"direction\">Do the following statements agree with the information given in Reading Passage 1? Choose TRUE, FALSE or NOT GIVEN.</p><div class=\"question-group\"><div class=\"question-line\" id=\"question-1\"><span class=\"qn\">1.</span> Trans fatty acids are found in all types of meat. <span class=\"live-input\">{{1}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"1\" title=\"Flag question 1\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-2\"><span class=\"qn\">2.</span> Health problems can be caused by the consumption of small amounts of trans fatty acids. <span class=\"live-input\">{{2}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"2\" title=\"Flag question 2\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-3\"><span class=\"qn\">3.</span> Experts consider that the trans fatty acids contained in animal products are unlikely to be a serious health risk. <span class=\"live-input\">{{3}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"3\" title=\"Flag question 3\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-4\"><span class=\"qn\">4.</span> In Britain, the intake of trans fatty acids is continuing to decline. <span class=\"live-input\">{{4}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"4\" title=\"Flag question 4\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-5\"><span class=\"qn\">5.</span> The amount of saturated fats in processed meats is being reduced by some major producers. <span class=\"live-input\">{{5}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"5\" title=\"Flag question 5\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-6\"><span class=\"qn\">6.</span> It is proving difficult to find a safe substitute for trans fatty acids. <span class=\"live-input\">{{6}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"6\" title=\"Flag question 6\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-7\"><span class=\"qn\">7.</span> Some people are still consuming larger quantities of trans fatty acids than the experts consider safe. <span class=\"live-input\">{{7}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"7\" title=\"Flag question 7\">⚐</button></div></div><h3>Questions 8–13</h3><p class=\"direction\">Complete the sentences below. Choose NO MORE THAN THREE WORDS from the passage for each answer.</p><div class=\"question-group\"><div class=\"question-line\" id=\"question-8\"><span class=\"qn\">8.</span> Scientists at Oxford University propose that information about trans fatty acids should be included on ________. <span class=\"live-input\">{{8}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"8\" title=\"Flag question 8\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-9\"><span class=\"qn\">9.</span> In food manufacture, the majority of trans fatty acids are created when ________ are solidified. <span class=\"live-input\">{{9}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"9\" title=\"Flag question 9\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-10\"><span class=\"qn\">10.</span> The likelihood of a person developing ________ is increased by trans fatty acid consumption. <span class=\"live-input\">{{10}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"10\" title=\"Flag question 10\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-11\"><span class=\"qn\">11.</span> In the UK, the ________ established a limit for the safe daily consumption of trans fatty acids. <span class=\"live-input\">{{11}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"11\" title=\"Flag question 11\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-12\"><span class=\"qn\">12.</span> Partially hydrogenated oils are no longer found in most UK manufactured salty ________. <span class=\"live-input\">{{12}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"12\" title=\"Flag question 12\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-13\"><span class=\"qn\">13.</span> Consumption of trans fatty acids in ________ is now higher than in the UK. <span class=\"live-input\">{{13}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"13\" title=\"Flag question 13\">⚐</button></div></div>"},{"title":"Psychosocial Value of Space","passage":"<p class=\"passage-par\"><strong class=\"para-letter\">A</strong> What would a building space look and feel like if it were designed to promote psychological and social well-being? How would it affect the senses, the emotions, and the mind? How would it affect behavioral patterns? For insights, it is useful to look not at buildings, but at zoos. Zoo design has gone through a radical transformation in the past several decades. Cages have been replaced by natural habitats and geographic clustering of animals. In some places, the animals are free-ranging and the visitors are enclosed in buses or trains moving through the habitat. Animals now exist in mixed species exhibits more like their natural landscapes. And, as in nature, the animals have much greater control over their behavior. They can be on view if they want, or out of sight. They forage, play, rest, mate and act like normal animals.</p>\n<p class=\"passage-par\"><strong class=\"para-letter\">B</strong> What brought about this transformation in philosophy and design? A key factor was concern over the animals&#x27; psychological and social well-being. Zoos could keep animals alive, but they couldn&#x27;t make them flourish. Caged animals often exhibit neurotic behaviors—pacing, repetitive motions, aggression, and withdrawal. In one famous example, an animal psychologist was hired by the Central Park Zoo to study a polar bear that spent the day swimming in endless figure eights in its small pool. This was not normal polar bear behavior and the zoo was concerned about it. After several days of observation, the animal psychologist offered a diagnosis. The bear was bored. To compensate for this unfortunate situation, the zoo added amenities and toys to the bear&#x27;s enclosure to encourage exploration and play.</p>\n<p class=\"passage-par\"><strong class=\"para-letter\">C</strong> Are there lessons that we can apply to building design? Some experts believe so: for example, biologist Stephen Boyden (1971) defines the optimum healthy environment as &#x27;the conditions which tend to promote or permit an animal optimal physiological, mental, and social performance in its natural or &quot;evolutionary&quot; environment.&#x27; Because humans evolved in a natural landscape, it is reasonable to turn to the natural environment for clues about preference patterns that may be applicable to building design. Drawing on habitat selection theory, ecologist Gordon Orians argues that humans are psychologically adapted to and prefer landscape features that characterized the African plain or savannah, the presumed site of human evolution. Although humans now live in many different habitats, Orians argues that our species&#x27; long history as mobile hunters and gatherers on the African savannahs should have left its mark on our psyche. If the &#x27;savannah hypothesis&#x27; is true, we would expect to find that humans intrinsically like and find pleasurable environments that contain the key features of the savannah most likely to have aided our ancestors&#x27; survival and well-being.</p>\n<p class=\"passage-par\"><strong class=\"para-letter\">D</strong> Although Boyden distinguishes between survival and well-being needs, they often overlap. For example, people clearly need food for survival and health. However, food often serves as the basis for bonding and relationship development. The ritual of sitting around a fire on the savannah or in a cave telling stories of the day&#x27;s events and planning for tomorrow may be an ancient carryover from Homo sapiens&#x27; hunting and gathering days. According to anthropologist Melvin Konner, the sense of safety and intimacy associated with the campfire may have been a factor in the evolution of intellectual progression as well as social bonds. Today&#x27;s hearth is the family kitchen at home, and the community places, such as cafes and coffee bars, where people increasingly congregate to eat, talk, read and work.</p>\n<p class=\"passage-par\"><strong class=\"para-letter\">E</strong> A growing body of research shows that building environments that connect people to nature are more supportive of human emotional well-being and cognitive performance than environments lacking these features. For instance, research by Roger Ulrich consistently shows that passive viewing of nature through windows promotes positive moods. Similarly, research by Rachel Kaplan found that workers with window views of trees had a more positive outlook on life than those doing similar work but whose window looked out onto a parking lot. Connection to nature also provides mini mental breaks that may aid the ability to concentrate, according to research by Stephen Kaplan. Terry Hartig and colleagues report similar results in a field experiment. People in their study who went for a walk in a predominantly natural setting achieved better on several office tasks requiring concentration than those who walked in a predominantly built setting or who quietly read a magazine indoors.</p>\n<p class=\"passage-par\"><strong class=\"para-letter\">F</strong> Studies of outdoor landscapes are providing evidence that the effects of nature on human health and well-being extend beyond emotional and cognitive functioning to social behavior and crime reduction. For instance, Francis Kuo found that outdoor nature buffers aggression in urban high-rise settings and enhances ability to deal with demanding circumstances. He also reported that planting trees in urban areas increases sociability by providing comfortable places for residents to talk with one another and develop friendships that promote mutual support.</p>\n<p class=\"passage-par\"><strong class=\"para-letter\">G</strong> A natural perspective also contributes important insights into comfort maintenance. Because people differ from one another in many ways (genetics, cultures, lifestyles) their ambient preferences vary. Furthermore, a given person varies over time depending upon his or her state of health, activities, clothing levels, and so forth. For most of human history, people have actively managed their surroundings as well as their behaviors to achieve comfort. Yet buildings continue to be designed with a &#x27;one size fits all&#x27; approach. Very few buildings or workstations enable occupants to control lighting, temperature, ventilation rates, or noise conditions. Although the technology is largely available to do this, the personal comfort systems have not sold well in the market place, even though research by Walter Kroner and colleagues at Rensselaer Polytechnic Institute shows that personal control leads to significant increases in comfort and morale.</p>","questions":"<h3>Questions 14–20</h3><p class=\"direction\">Reading Passage 2 has seven paragraphs, A–G. Choose the correct heading for each paragraph from the list of headings i–x.</p><div class=\"option-box\"><strong>List of Headings</strong><div><b>i</b> The influence of the seasons on productivity</div><div><b>ii</b> A natural way to anger management</div><div><b>iii</b> Natural building materials promote health</div><div><b>iv</b> Learning from experience in another field</div><div><b>v</b> Stimulating the brain through internal design features</div><div><b>vi</b> Current effects on the species of ancient experiences</div><div><b>vii</b> Uniformity is not the answer</div><div><b>viii</b> The negative effects of restricted spaces</div><div><b>ix</b> Improving occupational performance</div><div><b>x</b> The modern continuation of ancient customs</div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-14\"><span class=\"qn\">14.</span> Paragraph A <span class=\"live-input\">{{14}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"14\" title=\"Flag question 14\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-15\"><span class=\"qn\">15.</span> Paragraph B <span class=\"live-input\">{{15}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"15\" title=\"Flag question 15\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-16\"><span class=\"qn\">16.</span> Paragraph C <span class=\"live-input\">{{16}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"16\" title=\"Flag question 16\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-17\"><span class=\"qn\">17.</span> Paragraph D <span class=\"live-input\">{{17}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"17\" title=\"Flag question 17\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-18\"><span class=\"qn\">18.</span> Paragraph E <span class=\"live-input\">{{18}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"18\" title=\"Flag question 18\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-19\"><span class=\"qn\">19.</span> Paragraph F <span class=\"live-input\">{{19}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"19\" title=\"Flag question 19\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-20\"><span class=\"qn\">20.</span> Paragraph G <span class=\"live-input\">{{20}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"20\" title=\"Flag question 20\">⚐</button></div></div><h3>Questions 21–26</h3><p class=\"direction\">Match each person with the correct theory, A–I.</p><div class=\"option-box\"><strong>List of Theories</strong><div><b>A</b> Creating a green area can stimulate a sense of community.</div><div><b>B</b> People need adequate living space in order to be healthy.</div><div><b>C</b> Natural landscape can both relax and sharpen the mind.</div><div><b>D</b> Cooking together is an important element in human bonding.</div><div><b>E</b> People feel more at ease if they can adjust their environment.</div><div><b>F</b> Looking at a green environment improves people’s spirits.</div><div><b>G</b> Physical exercise improves creative thinking at work.</div><div><b>H</b> Man&#x27;s brain developed partly through regular association with peers.</div><div><b>I</b> We are drawn to places similar to the area where our species originated.</div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-21\"><span class=\"qn\">21.</span> Gordon Orians <span class=\"live-input\">{{21}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"21\" title=\"Flag question 21\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-22\"><span class=\"qn\">22.</span> Melvin Konner <span class=\"live-input\">{{22}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"22\" title=\"Flag question 22\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-23\"><span class=\"qn\">23.</span> Roger Ulrich <span class=\"live-input\">{{23}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"23\" title=\"Flag question 23\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-24\"><span class=\"qn\">24.</span> Stephen Kaplan <span class=\"live-input\">{{24}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"24\" title=\"Flag question 24\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-25\"><span class=\"qn\">25.</span> Francis Kuo <span class=\"live-input\">{{25}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"25\" title=\"Flag question 25\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-26\"><span class=\"qn\">26.</span> Walter Kroner <span class=\"live-input\">{{26}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"26\" title=\"Flag question 26\">⚐</button></div></div>"},{"title":"Educational and Professional Opportunities for Women in New Technologies","passage":"<p class=\"passage-par\">The principle that you don&#x27;t have to be a mechanic to drive a car can also be applied to Information and Communication Technologies (ICTs). Gone are the days when a computer user needed knowledge of a programming language. On one hand, this is good news for women. It is because women can now use computers without needing computer science qualifications that gives ICTs the potential to enhance women&#x27;s education. But, our lack of ICT skills is not praiseworthy. Feminist writers for many years have argued that if more women were engineers and scientists, we might live in a very different world. (Rothschild 1982)</p>\n<p class=\"passage-par\">In a review of five countries, Millar and Jagger examined women&#x27;s employment in ICT occupations. They found a pattern of a low proportion of female entrants, a significant &#x27;leaking&#x27; (Alper 1993) of those who enter to other areas of employment, and a ghetto of women in lower paid jobs. How did a new area of economic activity become gendered so quickly? An obvious answer could be that men have seen it as a desirable area and women have not.</p>\n<p class=\"passage-par\">It is often said that new industries are both &#x27;gender blind&#x27; (i.e. if you are good at your work you&#x27;ll succeed whatever your gender) and that they value &#x27;feminine&#x27; communication and &#x27;people&#x27; skills. But recent research does not bear this out. A study of a new high-tech ICT company (Woodfield 2000) employing highly qualified graduates showed that men were given management responsibility despite an acknowledgement by the company that they had poor management skills. And there was an unwillingness to give responsibilities to women who had these skills. It seems that jobs acquire gender quite quickly in some sectors.</p>\n<p class=\"passage-par\">In the 1980s and 1990s, interesting studies were done into the ways in which men and women think about the world. They argued for the validation of diverse ways of thinking, rather than a hierarchy with a particular kind of male intellectual tradition at the apex. Turkle (1984; 1996) has done similar work on the ways people interact with computers. She sees computers as tools used as an extension of our identities, with significant variations in the ways that men and women use them to explore and perform their gendered identities. This subtle way of understanding our relationship with technology, however, must go in parallel with a materialist view, which is that an underlying motivation for most ICT-based initiatives in work, education, leisure, citizenship is economic force.</p>\n<p class=\"passage-par\">We must also differentiate between the opportunities for employment offered by ICTs, and the tools they provide for education. We must beware of the inappropriate application of ICTs to a problem that would be better addressed in another way. Research into the effectiveness of ICTs as measured by student performance in Maths, suggests that for young children there is a negative relationship between classroom computer use and Maths performance. One researcher, Angrist, from MIT found when examining ICTs in the classroom that the set-up costs were obvious and the benefits much less so (Economist 2002). It could be more effective to have more teacher involvement and lower class sizes.</p>\n<p class=\"passage-par\">In 1963 Clark Kerr, the President of the University of California, coined the term &#x27;multiversity&#x27;, to suggest that universities were no longer based on a body of universal knowledge or a heterogeneous body of students. Higher education, professional education and life skills education are now being delivered by a variety of different universities, colleges and commercial companies. The distinctions between these are breaking down. Just when women are getting equal access to higher education and professional education, what constitutes higher level education and valid scholarly activity has been called into question through the creation of virtual universities. On the other hand, women are often claimed to have the most to gain from these new flexible and distributed kinds of education.</p>\n<p class=\"passage-par\">Although online education provides new opportunities for women it is also the source of new pressures. The term &#x27;Second Shift&#x27; was invented to identify the work/life balance of employed women. Women in paid employment did not substitute this for their domestic work; they struggled to carry out both obligations. Kramarae sees education in the new century as the &#x27;Third Shift&#x27;: &#x27;As lifelong learning and knowledge become ever more important, women and men find they juggle not only the demands of work and family, but also the demands of ... further education throughout their lives.&#x27; (2001)</p>\n<p class=\"passage-par\">ICTs - the Internet in particular - are seen as providing global access to key educational resources. However, access to information is a useless resource if you don&#x27;t have the skills to evaluate and use it. Shade (2002) distinguishes between the feminisation of the Internet, where women are targeted as consumers rather than citizens or learners; and feminist uses of the Internet where women develop content that creates opportunities for women.</p>\n<p class=\"passage-par\">Digital media may also produce inflexibility for women engaged in learning. A survey of open and distance learning students (Kirkup and Prümmer 1997; Kirkup 2001) demonstrated differences in the preferred learning styles of women and men. Women were uncomfortable with isolation and stated a desire for connection with others. Engagement in creating and maintaining networks and relationships is often cited as a reason why computer-mediated communication will be a &#x27;female&#x27; technology. Unfortunately, however, empirical work challenges this. Li (2002), in a study of university students in the UK and China, found that male students used e-mail more frequently, spent more time online, and engaged in more varied activities than women students. There is now a wealth of research on the gender differences of male and female online activity, all of which demonstrate the online environment creating a gendered world operating in similar ways to the material world.</p>","questions":"<h3>Questions 27–34</h3><p class=\"direction\">Match each person with the correct reported finding, A–K.</p><div class=\"option-box\"><strong>List of Reported Findings</strong><div><b>A</b> Men and women perceive their environment differently.</div><div><b>B</b> The advantages of ICTs in schools are difficult to specify.</div><div><b>C</b> Men see ICT as an exciting new area of employment.</div><div><b>D</b> Female students find working on their own unappealing.</div><div><b>E</b> A greater female representation in scientific and technical posts would have enormous benefits.</div><div><b>F</b> Women can be seen as both passive and active users of ICTs.</div><div><b>G</b> Female students can benefit most from ICTs and distance learning.</div><div><b>H</b> In Higher Education, men use a wider range of ICT skills than women.</div><div><b>I</b> A considerable number of women give up ICT posts to work in different fields.</div><div><b>J</b> The way the two genders regard computers reflects the differences in the way they develop their sense of self.</div><div><b>K</b> Certain new employment sectors are soon colonized by workers of one sex.</div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-27\"><span class=\"qn\">27.</span> Rothschild <span class=\"live-input\">{{27}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"27\" title=\"Flag question 27\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-28\"><span class=\"qn\">28.</span> Alper <span class=\"live-input\">{{28}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"28\" title=\"Flag question 28\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-29\"><span class=\"qn\">29.</span> Woodfield <span class=\"live-input\">{{29}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"29\" title=\"Flag question 29\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-30\"><span class=\"qn\">30.</span> Turkle <span class=\"live-input\">{{30}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"30\" title=\"Flag question 30\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-31\"><span class=\"qn\">31.</span> Angrist <span class=\"live-input\">{{31}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"31\" title=\"Flag question 31\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-32\"><span class=\"qn\">32.</span> Shade <span class=\"live-input\">{{32}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"32\" title=\"Flag question 32\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-33\"><span class=\"qn\">33.</span> Kirkup <span class=\"live-input\">{{33}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"33\" title=\"Flag question 33\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-34\"><span class=\"qn\">34.</span> Li <span class=\"live-input\">{{34}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"34\" title=\"Flag question 34\">⚐</button></div></div><h3>Questions 35–40</h3><p class=\"direction\">Complete the sentences below. Choose NO MORE THAN THREE WORDS from the passage for each answer.</p><div class=\"question-group\"><div class=\"question-line\" id=\"question-35\"><span class=\"qn\">35.</span> The term &#x27;________&#x27; refers to a company that is equally happy to promote workers of either sex. <span class=\"live-input\">{{35}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"35\" title=\"Flag question 35\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-36\"><span class=\"qn\">36.</span> It is clear that ICT developments in most fields are driven by ________. <span class=\"live-input\">{{36}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"36\" title=\"Flag question 36\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-37\"><span class=\"qn\">37.</span> The range of institutions providing high level instruction today is known as a ________. <span class=\"live-input\">{{37}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"37\" title=\"Flag question 37\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-38\"><span class=\"qn\">38.</span> Women who are working find it hard to get their ________ right. <span class=\"live-input\">{{38}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"38\" title=\"Flag question 38\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-39\"><span class=\"qn\">39.</span> The way workers of both sexes now face having to fit children, work and continued learning into their lives is called the ________. <span class=\"live-input\">{{39}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"39\" title=\"Flag question 39\">⚐</button></div></div><div class=\"question-group\"><div class=\"question-line\" id=\"question-40\"><span class=\"qn\">40.</span> Women are thought to be suited to computer work as it involves developing ________ and ________. <span class=\"live-input\">{{40}}</span><button class=\"flag-btn\" type=\"button\" data-flag=\"40\" title=\"Flag question 40\">⚐</button></div></div>"}],"writing":[{"title":"Dry Method of Coffee Production","html":"<p class=\"direction\">You should spend about 20 minutes on this task.</p><p><strong>The illustrations below show how coffee is sometimes produced.</strong></p><p><strong>Summarise the information by selecting and reporting the main features.</strong></p><p>Write at least 150 words.</p>"},{"title":"Western Diets","html":"<p class=\"direction\">You should spend about 40 minutes on this task.</p><p>Present a written argument or case to an educated reader with no specialist knowledge of the following topic.</p><div class=\"writing-topic\"><p><strong>Some people claim that what people eat in many Western countries is unhealthy and that their diet is getting worse. Critics say that these countries should change their diet.</strong></p><p><strong>What are your opinions on this?</strong></p></div><p>Give reasons for your answer and include any relevant examples from your own knowledge or experience.</p><p>Write at least 250 words.</p>"}],"speaking":[{"title":"Introduction & Interview","html":"<h3>What you do</h3>\n<p class=\"speaking-question\">• Are you a student?</p>\n<p class=\"speaking-question\">• Where do you study?</p>\n<p class=\"speaking-question\">• What do you like most about your college? (Why?)</p>\n<p class=\"speaking-question\">• What subjects would you like to study in future? (Why?)</p>\n<h3>Clothes</h3>\n<p class=\"speaking-question\">• How do you prefer to buy your clothes (e.g. shops, large stores, internet)? (Why?)</p>\n<p class=\"speaking-question\">• How important is fashion to you? (Why?)</p>\n<p class=\"speaking-question\">• How much do you think we can judge people by the clothes they wear?</p>\n<h3>Hobbies</h3>\n<p class=\"speaking-question\">• What hobbies do you do regularly?</p>\n<p class=\"speaking-question\">• What benefits can people get from their hobbies?</p>\n<p class=\"speaking-question\">• Which new hobby would you like to try? (Why?)</p>"},{"title":"Individual Long Turn","html":"<p class=\"speaking-cue\">Describe how you like to communicate with your friends</p>\n<p>(e.g. by mobile phone, email, texts).</p>\n<h3>You should say:</h3>\n<p class=\"speaking-question\">• how you prefer to communicate with your friends</p>\n<p class=\"speaking-question\">• how often you use this method of communication</p>\n<p class=\"speaking-question\">• what disadvantages there are to communicating in this way</p>\n<p>and explain why you prefer this method of communication.</p>\n<h3>Rounding-off question</h3>\n<p>Do most of your friends communicate in this way?</p>"},{"title":"Discussion","html":"<h3>Changes in communication</h3>\n<p class=\"speaking-question\">• Can you describe how people used to communicate fifty years ago?</p>\n<p class=\"speaking-question\">• What were/are the good points about writing and receiving letters?</p>\n<p class=\"speaking-question\">• How do you think methods of communication will change in the future?</p>"}]},"keys":{"listening":{"1":["weekend trips"],"2":["competitions"],"3":["125"],"4":["club secretary"],"5":["twice a month","twice per month"],"6":["spring"],"7":["weekly"],"8":["equipment"],"9":["magazine"],"10":["exhibition"],"11":["E"],"12":["A"],"13":["G"],"14":["D"],"15":["B"],"16":["6 weeks","six weeks"],"17":["email"],"18":["£1.50","1.50","1.5"],"19":["yellow form"],"20":["ordering"],"21":["D"],"22":["C"],"23":["B"],"24":["3rd term","third term"],"25":["industry"],"26":["plans"],"27":["new lab","new laboratory"],"28":["seminars"],"29":["pairs"],"30":["an interview","interview"],"31":["select"],"32":["invest"],"33":["research"],"34":["sell"],"35":["buy"],"36":["calculate"],"37":["29","twenty nine"],"38":["manufacturing"],"39":["import prices"],"40":["February 5th","February fifth","5th February"]},"reading":{"1":["FALSE"],"2":["TRUE"],"3":["TRUE"],"4":["NOT GIVEN"],"5":["NOT GIVEN"],"6":["TRUE"],"7":["TRUE"],"8":["food labels"],"9":["vegetable oils"],"10":["heart disease","cardiovascular disease"],"11":["Department of Health"],"12":["biscuits and crisps","crisps and biscuits"],"13":["the USA","USA"],"14":["iv"],"15":["viii"],"16":["vi"],"17":["x"],"18":["ix"],"19":["ii"],"20":["vii"],"21":["I"],"22":["H"],"23":["F"],"24":["C"],"25":["A"],"26":["E"],"27":["E"],"28":["I"],"29":["K"],"30":["J"],"31":["B"],"32":["F"],"33":["D"],"34":["H"],"35":["gender blind"],"36":["economic force"],"37":["multiversity"],"38":["work/life balance"],"39":["Third Shift"],"40":["networks and relationships","relationships and networks"]}},"audio":["LISTENING_PART_1.mp3","LISTENING_PART_2.mp3","LISTENING_PART_3.mp3","LISTENING_PART_4.mp3"]};
